                <tr><td><strong>{{ $service->name }}</strong><br><span style="color:var(--muted)">Empresa {{ $service->empresa_codigo }} · {{ ucfirst($service->category) }}</span></td>
                    <td><span class="status" style="{{ $service->active ? 'background:#173c31;color:#7ce5bf' : '' }}">{{ $service->active ? 'Ativo' : 'Pausado' }}</span></td>
                    <td>A cada {{ $service->frequency_minutes }} min<br><span style="color:var(--muted)">{{ $service->lookback_days }} dias por consulta</span></td>
                    <td>@if($lastRun)<strong>{{ $lastRun->status === 'success' ? 'Concluída' : ($lastRun->status === 'failed' ? 'Falhou' : 'Executando') }}</strong><br><span style="color:var(--muted)">{{ optional($lastRun->started_at)->format('d/m/Y H:i') }} · {{ $lastRun->received }} recebidos</span>@else<span style="color:var(--muted)">Nunca executado</span>@endif</td>
                    <td><div style="display:flex;gap:7px;align-items:center"><form method="POST" action="{{ route('admin.services.run', $service) }}">@csrf<button class="action" type="submit" style="cursor:pointer;color:#bfe0d6">Executar</button></form>
                        @if($service->active)<form method="POST" action="{{ route('admin.services.pause', $service) }}">@csrf<button class="action" type="submit" style="cursor:pointer">Pausar</button></form>
                        @else<form method="POST" action="{{ route('admin.services.resume', $service) }}">@csrf<button class="action" type="submit" style="cursor:pointer">Ativar</button></form>@endif
                        <button class="toggle" type="button" data-detail="service-{{ $service->id }}" title="Ver detalhes" aria-label="Ver detalhes"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m6 9 6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div></td></tr>
                <tr class="detail-row"><td colspan="5"><div class="detail" id="service-{{ $service->id }}"><div class="detail-content">
                    <div><h3>Como funciona</h3><p>Consulta os títulos a receber da empresa {{ $service->empresa_codigo }} em uma janela móvel de {{ $service->lookback_days }} dias. Registros novos são inseridos e títulos existentes são atualizados pela combinação de empresa e <code>tituloCodigo</code>.</p>
                        <div class="flow"><span class="step">Agendador</span><span class="arrow">→</span><span class="step">Fila financeira</span><span class="arrow">→</span><span class="step">WebPosto</span><span class="arrow">→</span><span class="step">titulos_receber</span></div></div>
                    <div class="facts"><div class="fact"><span>Último acionamento</span><strong>{{ optional($service->last_started_at)->format('d/m/Y H:i:s') ?: 'Nunca' }}</strong></div><div class="fact"><span>Última conclusão</span><strong>{{ optional($service->last_completed_at)->format('d/m/Y H:i:s') ?: 'Nunca' }}</strong></div><div class="fact"><span>Próxima execução</span><strong>{{ $service->active ? (optional($service->next_run_at)->format('d/m/Y H:i:s') ?: 'Aguardando agenda') : 'Serviço pausado' }}</strong></div><div class="fact"><span>Destino</span><strong>webposto.titulos_receber</strong></div></div>
                    <div class="fields"><h3>Campos de controle no banco de integração</h3><div class="chips">@foreach(['name','slug','category','resource','empresa_codigo','frequency_minutes','lookback_days','active','last_started_at','last_completed_at','next_run_at','last_error'] as $field)<span class="chip">{{ $field }}</span>@endforeach</div></div>
                    <div class="fields"><h3>Histórico de execução</h3><div class="chips">@foreach(['status','period_start','period_end','received','inserted','updated','unchanged','skipped','error','started_at','finished_at'] as $field)<span class="chip">{{ $field }}</span>@endforeach</div></div>
                </div></div></td></tr>
            @empty
                <tr><td colspan="5"><div class="empty"><div class="empty-icon">◇</div><strong>Nenhum serviço configurado</strong></div></td></tr>
            @endforelse
        </tbody></table></section>
    </main>
</div><script>document.querySelectorAll('.toggle').forEach(button=>button.addEventListener('click',()=>{const panel=document.getElementById(button.dataset.detail);const open=panel.classList.toggle('open');button.classList.toggle('open',open);button.setAttribute('aria-expanded',open?'true':'false')}));</script></body></html>
